# Verbal Ability: grammar and correct usage (English). Key first.
ITEMS = [
    # ---------- Practice Test 1 (Professional) ----------
    S(1, 1, "Subject-verb agreement", "Choose the word that best completes the sentence: \"Each of the applicants ___ required to submit a photocopy of a valid ID.\"",
      ["is", "are", "were", "have been"],
      "\"Each\" is singular, so it takes the singular verb \"is\". The plural noun \"applicants\" sits inside the prepositional phrase and does not control the verb."),
    S(1, 2, "Subject-verb agreement", "Choose the word that best completes the sentence: \"Mathematics ___ my favorite subject in high school.\"",
      ["was", "were", "are", "have been"],
      "\"Mathematics\" ends in -s but names one subject, so it takes a singular verb. The past time \"in high school\" needs \"was\"."),
    S(1, 1, "Verb tense", "Choose the word that best completes the sentence: \"By the time the director arrived, the staff ___ the hall.\"",
      ["had cleaned", "has cleaned", "cleans", "will clean"],
      "The cleaning was finished before another past action (the director arrived), so the past perfect \"had cleaned\" is correct."),
    S(1, 2, "Pronoun case", "Choose the word that best completes the sentence: \"The supervisor gave the new forms to Ana and ___.\"",
      ["me", "I", "myself", "mine"],
      "\"To Ana and me\": the pronoun is the object of the preposition \"to\", so the object form \"me\" is needed. Drop \"Ana and\" to check: \"gave the forms to me\"."),
    S(1, 2, "Pronoun case", "Choose the word that best completes the sentence: \"___ do you think will be named the employee of the month?\"",
      ["Who", "Whom", "Whose", "Which"],
      "The pronoun is the subject of \"will be named\" (\"you think he will be named\"), so the subject form \"Who\" is correct. \"Do you think\" is only an inserted clause."),
    S(1, 1, "Prepositions", "Choose the word that best completes the sentence: \"The new policy will take effect ___ January 2.\"",
      ["on", "in", "at", "by"],
      "Use \"on\" with a specific date or day, \"in\" with months and years, and \"at\" with clock times."),
    S(1, 2, "Conditional", "Choose the words that best complete the sentence: \"If I ___ the deadline earlier, I would have filed my application on time.\"",
      ["had known", "have known", "knew", "would know"],
      "A past unreal condition uses \"if\" + past perfect (\"had known\") with \"would have\" + past participle in the main clause."),
    S(1, 2, "Correct usage", "Which sentence is grammatically correct?",
      ["Fewer people attended this year's seminar.", "Less people attended this year's seminar.", "Lesser people attended this year's seminar.", "Few people has attended this year's seminar."],
      "\"Fewer\" is used with things you can count (people); \"less\" is for amounts that cannot be counted, such as water or time."),
    S(1, 3, "Parallelism", "Which sentence is grammatically correct?",
      ["She likes reading, writing and cooking.", "She likes reading, writing and to cook.", "She likes to read, writing and cooking.", "She likes reading, to write and cook."],
      "Items in a series should have the same form. \"Reading, writing and cooking\" are all -ing forms; the others mix -ing forms with infinitives."),
    S(1, 3, "Modifiers", "Which sentence is grammatically correct?",
      ["Walking to the office, I saw the old building.", "Walking to the office, the old building was seen.", "Walking to the office, the building looked old.", "While walking to the office, the building was old."],
      "The opening phrase must describe the subject that follows it. Only \"I\" can be walking; in the other sentences the building seems to be walking, which is a dangling modifier."),

    # ---------- Practice Test 2 (Subprofessional) ----------
    S(2, 1, "Subject-verb agreement", "Choose the word that best completes the sentence: \"The list of requirements ___ posted on the bulletin board.\"",
      ["is", "are", "were", "have"],
      "The subject is \"list\", which is singular, so the verb is \"is\". \"Of requirements\" only describes the list."),
    S(2, 1, "Subject-verb agreement", "Choose the word that best completes the sentence: \"My brother and my cousin ___ working in the same municipal office.\"",
      ["are", "is", "was", "has"],
      "Two subjects joined by \"and\" make a plural subject, so the plural verb \"are\" is correct."),
    S(2, 1, "Verb tense", "Choose the word that best completes the sentence: \"Yesterday, the barangay captain ___ the new health center.\"",
      ["opened", "opens", "has opened", "will open"],
      "\"Yesterday\" marks a finished past time, so the simple past \"opened\" is correct. The present perfect is not used with a stated past time."),
    S(2, 2, "Verb tense", "Choose the words that best complete the sentence: \"She ___ in this office since 2018.\"",
      ["has worked", "works", "worked", "is working"],
      "\"Since 2018\" describes an action that began in the past and continues now, which calls for the present perfect \"has worked\"."),
    S(2, 1, "Articles", "Choose the word that best completes the sentence: \"Please submit ___ honest answer to every question.\"",
      ["an", "a", "the", "any"],
      "\"Honest\" begins with a vowel sound because the h is silent, so it takes \"an\"."),
    S(2, 2, "Subject-verb agreement", "Choose the word that best completes the sentence: \"One of the computers in the records section ___ not working.\"",
      ["is", "are", "were", "have been"],
      "The subject is \"one\", which is singular, so the verb is \"is\". \"Of the computers\" does not make the subject plural."),
    S(2, 2, "Prepositions", "Choose the word that best completes the sentence: \"The office is closed ___ Saturdays and Sundays.\"",
      ["on", "in", "at", "for"],
      "Days of the week take \"on\": on Monday, on Saturdays."),
    S(2, 2, "Correct usage", "Which sentence is grammatically correct?",
      ["Their forms are on the table over there.", "There forms are on the table over their.", "They're forms are on the table over there.", "Their forms are on the table over their."],
      "\"Their\" shows ownership, \"there\" shows place, and \"they're\" means \"they are\". Only the first sentence uses each correctly."),
    S(2, 3, "Correct usage", "Which sentence is grammatically correct?",
      ["The report was written by Liza and me.", "The report was written by Liza and I.", "The report was wrote by Liza and me.", "The report were written by Liza and me."],
      "\"By\" takes the object form \"me\", the passive needs the past participle \"written\", and the singular subject \"report\" takes \"was\"."),
    S(2, 2, "Comparison", "Choose the word that best completes the sentence: \"Of the three applicants, Marco is the ___.\"",
      ["most qualified", "more qualified", "qualifiedest", "much qualified"],
      "When three or more are compared, use the superlative (\"most qualified\"). \"More\" compares only two."),

    # ---------- Drill only ----------
    S(0, 2, "Subject-verb agreement", "Choose the word that best completes the sentence: \"The committee ___ its decision after a long meeting.\"",
      ["announced", "announce", "have announce", "announcing"],
      "\"Committee\" acting as one body is singular, which the singular pronoun \"its\" confirms, so it takes the singular past form \"announced\"."),
    S(0, 2, "Verb forms", "Choose the word that best completes the sentence: \"The documents have already been ___ to the regional office.\"",
      ["sent", "send", "sended", "sending"],
      "After \"have been\" the passive needs the past participle. The past participle of \"send\" is \"sent\"; \"sended\" is not a word."),
    S(0, 3, "Correct usage", "Which sentence is grammatically correct?",
      ["The new rule affects every office.", "The new rule effects every office.", "The new rule affect every office.", "The new rule effect every office."],
      "\"Affect\" is the verb meaning to influence; \"effect\" is usually a noun (a result). The singular subject \"rule\" also needs \"affects\"."),
]
